CREATE POLICY "Screenshots are readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'screenshots');
CREATE POLICY "Users can upload their own screenshots" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can delete their own screenshots" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'screenshots' AND (storage.foldername(name))[1] = auth.uid()::text);